int queen_recursive(int r, int *c, int n)
{
    int nsolutions = 0;

    if (r == n)
        return 1;
    for (int i = 0; i < n; i++) {
        c[r] = i;
        if (is_valid_queen_placement(r, c) == 1)
            nsolutions = nsolutions + queen_recursive(r + 1, c, n);
        c[r] = 0;
    }
    return nsolutions;
}

