int truc(int *j, int *len, int *good, char *res)
{
    if ((*j == *len) && good)
        return 1;
    if (*j == *len)
        *j = 0;
    return 0;
}

void mdr(int *good, int *j)
{
    *good = 1;
    ++(*j);
}

char *my_strstr(char *str, char const *to_find)
{
    int len = getlen(to_find);
    int good = 0;
    int j = 0;
    char *res = 0;

    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] == to_find[0] && !good) {
            mdr(&good, &j);
            res = &str[i];
        }
        if ((str[i] != to_find[j]) && good) {
            good = 0;
            j = 0;
        }
        if (str[i] == to_find[j])
            ++j;
        if (truc(&j, &len, &good, res))
